/**
 * @param {number} n
 * @param {number} limit
 * @return {number}
 */
var distributeCandies = function(n, limit) {
    function c2(x) {
        if (x < 0n) return 0n;
        return (x + 2n) * (x + 1n) / 2n;
    }
    const bn = BigInt(n), bl = BigInt(limit);
    const L = bl + 1n;
    const ans = c2(bn) - 3n * c2(bn - L) + 3n * c2(bn - 2n * L) - c2(bn - 3n * L);
    return Number(ans);
};
